class EvidenceTests(unittest.TestCase):
    def assess(self,raw=CONTROL,**kw):
        return assess_cycles(raw,2,['449941297'],mode=2,identity=kw.pop('identity',IDENTITY),**kw)
    def reject(self,raw): self.assertEqual(self.assess(raw)['status'],'FAIL')
    def test_control_is_parser_only(self):
        r=self.assess();self.assertEqual(r['status'],'PASS',r);self.assertEqual(r['concurrent_invocation_overlap'],'NOT_RUN');self.assertEqual(r['milestone'],'PARTIAL')
    def test_physical_events_required_independently_of_metadata(self):
        for prefix in ('[AE-TLB]','[AE-UNMAP]','[AE-PMM]','[AE-MAP]','[CE-REAP]'):
            self.reject('\n'.join(l for l in CONTROL.splitlines() if not l.startswith(prefix)))
    def test_each_required_transition_is_necessary(self):
        lines=CONTROL.splitlines()
        for i,l in enumerate(lines):
            required=l.startswith(('[AE-GRANT]','[AE-MAP]','[AE-UNMAP]','[AE-TLB]','[AE-PMM]','[AE-TERMINAL]','[CE-REAP]'))
            required |= l.startswith('[CE-TARGET]') and any('event='+e+' ' in l for e in ('committed','fresh'))
            required |= l.startswith('[CE-STATE]') and any('event='+e+' ' in l for e in ('committed','deferred','late-denied','account-unmapped','cancel-observed','supervisor-clean','caller-consumed'))
            if required:
                with self.subTest(line=l):self.reject('\n'.join(lines[:i]+lines[i+1:]))
    def test_exact_identities_and_generation(self):
        for key in ('caller','caller_inc','caller_vm','issuer','issuer_inc','issuer_vm','frame','endpoint','generation','object'):
            line=next(l for l in CONTROL.splitlines() if l.startswith('[AE-GRANT]') and 'event=selected ' in l)
            value=next(v for v in line.split() if v.startswith(key+'='))
            self.reject(CONTROL.replace(line,line.replace(value,key+'=999'),1))
    def test_duplicate_terminal_retirement_and_free_rejected(self):
        for prefix in ('[AE-GRANT]','[AE-TERMINAL]','[AE-PMM]','[CE-REAP]'):
            line=next(l for l in CONTROL.splitlines() if l.startswith(prefix))
            self.reject(CONTROL+'\n'+line)
        self.reject(CONTROL.replace('event=free object=1','event=free object=1 object=2'))
    def test_receipts_and_reaping_are_not_metadata_substitutes(self):
        self.reject(CONTROL.replace('receipts=0','receipts=1'))
        self.reject(CONTROL.replace('active=0','active=2'))
        self.reject(CONTROL.replace('owning=255','owning=0'))
        self.reject(CONTROL.replace('views=0','views=1'))
        self.reject(CONTROL.replace('class=0','class=1'))
    def test_missing_authority_and_lifecycle_assertions_fail(self):
        for event in ('foreign-live-authority-denied','foreign-adoption-denied','caller-endpoint-retired','worker-ready'):
            self.reject('\n'.join(l for l in CONTROL.splitlines() if 'event='+event+' ' not in l))
        self.reject(CONTROL.replace('[SCHED] process_reaped','[METHOD] reaped'))
    def test_identity_faults_and_driver_failure_fail_closed(self):
        self.assertEqual(self.assess(identity=None)['status'],'FAIL')
        self.assertEqual(self.assess(failure={'type':'TimeoutError'})['status'],'FAIL')
        self.reject(CONTROL+'\nPANIC')
        self.assertEqual(assess_cycles(CONTROL,2,['449941297','missing'],mode=2,identity=IDENTITY)['status'],'FAIL')

if __name__=='__main__':unittest.main()
